    soknadStartVerdier + soknadUføreVerdier + STATSBORGERSKAP_ANDRE_LAND + soknadSluttVerdier

val forventetSoknadAlderVerdier =
    soknadStartVerdier + soknadAlderVerdier + STATSBORGERSKAP_ANDRE_LAND + soknadSluttVerdier

